//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry at the given zero-based retry index.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let delay = if retry_index >= 64
            || (retry_index > 0 && self.base_delay_ms > (u64::MAX >> retry_index))
        {
            u64::MAX
        } else {
            self.base_delay_ms << retry_index
        };
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_doubles_and_saturates_at_maximum() {
        let config = RetryConfig {
            max_attempts: 10,
            base_delay_ms: 25,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(0), 25);
        assert_eq!(config.delay_for_retry(1), 50);
        assert_eq!(config.delay_for_retry(2), 100);
        assert_eq!(config.delay_for_retry(10), 100);
    }

    #[test]
    fn delay_overflow_saturates_instead_of_wrapping() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 3,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(63), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is invalid per the configuration contract; returning the
    // first error keeps this API total without introducing a new error type.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt < max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempt - 1));
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    #[test]
    fn retries_transient_errors_until_success() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let config = RetryConfig {
            max_attempts: 2,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still down".into())));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures_with_a_bounded_schedule() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 25,
        max_delay_ms: 60,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 5 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![25, 50, 60, 60]);
}
